<?php
namespace App\Livewire\LMS\Announcements;
use App\Models\{Announcement,School,SchoolClass,Subject}; use Carbon\Carbon; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\{Rule,ValidationException}; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $title='',$content='',$audience='school',$classId='',$subjectId='',$publishedAt='',$expiresAt='';
public function mount():void{$this->authorize('viewAny',Announcement::class);} public function create():void{$this->authorize('create',Announcement::class);$this->resetForm();$this->showFormModal=true;} public function edit(Announcement $announcement):void{$this->authorize('update',$announcement);$this->editingId=$announcement->id;$this->title=$announcement->title;$this->content=$announcement->content;$this->audience=$announcement->audience;$this->classId=(string)($announcement->school_class_id??'');$this->subjectId=(string)($announcement->subject_id??'');$this->publishedAt=$announcement->published_at?->format('Y-m-d\TH:i')??'';$this->expiresAt=$announcement->expires_at?->format('Y-m-d\TH:i')??'';$this->showFormModal=true;}
public function save():void{$item=$this->editingId?Announcement::findOrFail($this->editingId):null;$this->authorize($item?'update':'create',$item??Announcement::class);try{$data=$this->validate(['title'=>['required','string','max:255'],'content'=>['required','string','max:50000'],'audience'=>['required',Rule::in(['school','class','subject'])],'classId'=>['nullable','integer',Rule::exists('school_classes','id')],'subjectId'=>['nullable','integer',Rule::exists('subjects','id')],'publishedAt'=>['nullable','date'],'expiresAt'=>['nullable','date','after:publishedAt']]);if($data['audience']==='class'&&blank($data['classId'])){$this->addError('classId','Choose a class audience.');return;}if($data['audience']==='subject'&&blank($data['subjectId'])){$this->addError('subjectId','Choose a subject audience.');return;}Announcement::updateOrCreate(['id'=>$item?->id],['school_id'=>School::query()->value('id'),'school_class_id'=>$data['audience']==='class'?$data['classId']:null,'subject_id'=>$data['audience']==='subject'?$data['subjectId']:null,'created_by'=>$item?->created_by??auth()->id(),'title'=>$data['title'],'content'=>strip_tags($data['content'],'<p><br><strong><em><u><ol><ul><li><blockquote><h2><h3><h4>'),'audience'=>$data['audience'],'published_at'=>filled($data['publishedAt'])?Carbon::parse($data['publishedAt']):now(),'expires_at'=>filled($data['expiresAt'])?Carbon::parse($data['expiresAt']):null]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title($item?'Announcement updated':'Announcement published')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the announcement')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save announcement')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(Announcement $item):void{$this->authorize('delete',$item);$this->deletingId=$item->id;$this->showDeleteModal=true;} public function delete():void{$item=Announcement::findOrFail($this->deletingId);$this->authorize('delete',$item);$item->delete();$this->showDeleteModal=false;LivewireAlert::title('Announcement archived')->success()->asToast()->position('top-end')->show();} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','title','content','audience','classId','subjectId','publishedAt','expiresAt']);$this->audience='school';$this->resetValidation();} public function render(){$schoolId=School::query()->value('id');return view('livewire.lms.announcements.index',['announcements'=>Announcement::where('school_id',$schoolId)->latest('published_at')->get(),'classes'=>SchoolClass::whereHas('academicYear',fn($q)=>$q->where('school_id',$schoolId))->get(),'subjects'=>Subject::where('school_id',$schoolId)->get()]);}}
